// The Lucide icon set (https://lucide.dev, ISC licence; chevron-right and lock derive from Feather, MIT): the 14 glyphs of the design review
// (section 2.5) plus lock-open, as 1-bit bitmaps in app/ui/fonts/neupod_icons_{16,24,36}.c (generated by tools/gen_ui_fonts.sh). A glyph is
// drawn by a label that uses the icon font (ui_icon() in ui_internal.h), so it takes its colour from a theme token like any text.
// Battery, signal bars and the busy dots are drawn shapes, not glyphs. The code points are the Lucide font's own.
#ifndef NEUPOD_UI_ICONS_H
#define NEUPOD_UI_ICONS_H

#define UI_ICON_CHEVRON_RIGHT "\xEE\x81\xAF" /* U+E06F */
#define UI_ICON_PLAY "\xEE\x84\xBC"          /* U+E13C */
#define UI_ICON_PAUSE "\xEE\x84\xAE"         /* U+E12E */
#define UI_ICON_SKIP_BACK "\xEE\x85\x9F"     /* U+E15F */
#define UI_ICON_SKIP_FORWARD "\xEE\x85\xA0"  /* U+E160 */
#define UI_ICON_SHUFFLE "\xEE\x85\x9E"       /* U+E15E */
#define UI_ICON_REPEAT "\xEE\x85\x86"        /* U+E146 */
#define UI_ICON_REPEAT_1 "\xEE\x87\xBD"      /* U+E1FD */
#define UI_ICON_VOLUME "\xEE\x86\xAB"        /* U+E1AB (volume-2) */
#define UI_ICON_BLUETOOTH "\xEE\x81\x9C"     /* U+E05C */
#define UI_ICON_WIFI "\xEE\x86\xAE"          /* U+E1AE */
#define UI_ICON_LOCK "\xEE\x84\x8B"          /* U+E10B */
#define UI_ICON_FOLDER "\xEE\x83\x97"        /* U+E0D7 */
#define UI_ICON_FILE "\xEE\x83\x80"          /* U+E0C0 */
#define UI_ICON_LOCK_OPEN "\xEE\x84\x8C"     /* U+E10C */

#endif // NEUPOD_UI_ICONS_H
